// No auto-created empty custom workout may survive: purge 0-step customs
// saved by older builds (audit #30), and their orphaned edits.
{const purgedIds=custom.filter(p=>(p.days?.[0]?.steps?.length||0)===0&&!(edits[`${p.id}:0`]?.length>0)).map(p=>p.id);if(purgedIds.length){custom=custom.filter(p=>!purgedIds.includes(p.id));for(const k of Object.keys(edits))if(purgedIds.some(id=>k.startsWith(id+':')))delete edits[k];try{localStorage.setItem(KEY,JSON.stringify({prefs,history,edits,custom,onboarded,ob,checkpoint:saved.checkpoint||null}))}catch{}}}
